def lin(c):
    c=c/255; return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def L(r,g,b): return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b)
Lf=L(112,185,237); Lb=L(0x17,0x23,0x36)
print('L fill %.4f L panel %.4f contrast %.2f:1'%(Lf,Lb,(Lf+0.05)/(Lb+0.05)))
from PIL import Image
im=Image.open('assets/ready-confirmed.png').convert('RGBA'); px=im.load()
rows={}
for y in range(16):
    xs=[x for x in range(16) if px[x,y][3]]
    if xs: rows[y]=xs
for y,xs in rows.items():
    runs=[];s=xs[0];p=xs[0]
    for x in xs[1:]:
        if x!=p+1: runs.append((s,p)); s=x
        p=x
    runs.append((s,p)); print(y,runs)
# 8-connected components and 4-connected
import collections
def comps(conn):
    seen=set();n=0
    for y in range(16):
        for x in range(16):
            if px[x,y][3] and (x,y) not in seen:
                n+=1;st=[(x,y)];seen.add((x,y))
                while st:
                    cx,cy=st.pop()
                    for dx in (-1,0,1):
